{
  "case_id": "xsu_sg_003_severity_assessment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret fremstiller sværhedsgraden som et spørgsmål om, om den studerende 'stort set ikke kan påtage sig erhvervsarbejde' og om en generel arbejdsevnevurdering. Det er ikke det, ekspertrubrikken og afsnit 3.4.1.2 siger. Svaret tilføjer også ekskluderende udsagn om økonomi, studietid og jobbenes studierelevans og geografi, som der ikke er støtte for. Kernen mangler: den individuelle lægefaglige helhedsvurdering, behandling, restsymptomer, medvirken og sygdomsforløb."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Af de fire kritiske elementer er kun et svagt spor af det første til stede ('konkrete, varige funktionsnedsættelse', art og grad). Det andet element, påvirkning af dagligt funktionsniveau, er ikke med. Behandling, effekt, restsymptomer, bivirkninger og rimelig medvirken er udeladt. Det samme gælder sygdommens varighed, gentagne perioder og tilbagefaldsrisiko. Lægefaglig dokumentation og individuel helhedsvurdering af aktuelle symptomer nævnes heller ikke."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Spørgsmålet er, hvad Udbetaling Danmark lægger vægt på ved sværhedsgraden. Svaret bruger det meste af teksten på en generel arbejdsevnevurdering og på negative afgrænsninger (økonomi, studietid, studierelevans, geografi) i stedet for de momenter, der faktisk indgår i vurderingen. Det besvarer derfor ikke de væsentlige dele af spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret angiver kilder, bl.a. vejledning nr. 10157 og to ankenævnsafgørelser, og nogle udsagn er knyttet til dem med fodnotemarkeringer. Flere væsentlige udsagn er markeret 'uden kilde'. Under reviewerens ordlyd, hvor kravet kun er, at der er en identificerbar kilde, er kriteriet opfyldt."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "De nævnte kilder er Retsinformation-dokumenter, herunder vejledning VEJ nr. 10157 af 05/10/2026 og ankenævnsafgørelser, og de er autoritative og relevante for handicaptillæg. Vejledningen svarer til den frosne kilde. Svaret selv tilkendegiver, at nogle kilder er uverificerede."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Der er ingen passage, der viser, at den centrale vurdering er 'stort set ikke kan påtage sig erhvervsarbejde', og afsnit 3.4.1.2 nævner heller ikke en 'generel arbejdsevnevurdering'. Flere påstande er markeret 'uden kilde': at økonomi, forlænget studietid, studierelevans og geografi ikke indgår. Den fremlagte vejledningspassage støtter kun, at art og grad vurderes, og at funktionsnedsættelsen skal være varig og konkret. Resten er ikke dækket."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en tærskel ('stort set ikke ... i nævneværdigt omfang'), en test om studenterjob 'med de ressourcer, den pågældende har' og en række udelukkelser: økonomiske forhold, forlænget studietid, jobbenes studierelevans og geografi. Intet af dette er støttet i det udleverede materiale. Den afsluttende tommelfingerregel 'jo mere ... desto mere taler det for' er også uden støtte."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Den krævede kvalifikation er, at momenterne blot er eksempler i en konkret individuel helhedsvurdering. Svaret fremstiller i stedet et snævert test og en række absolutte udelukkelser. Der er ingen 'blandt andet' eller 'f.eks.' og intet om, at vurderingen er samlet og individuel."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svarets trin er indbyrdes sammenhængende: først art og grad, derefter følgerne for arbejdsevnen, derefter en generel arbejdsevnevurdering og til sidst en kort opsummering. Konklusionen følger af svarets egne trin, selv om trinene er juridisk ukorrekte i forhold til kilderne."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør en eksemplificerende, skønsbaseret helhedsvurdering til en fast test med absolutte udelukkelser ('Der lægges derimod ikke vægt på ...', 'indgår heller ikke'). Det udtrykker også, at vurderingen 'i praksis' er en generel arbejdsevnevurdering, uden at kilden bærer det."
    }
  },
  "xhaile_coverage": {
    "A14": {
      "label": "no",
      "reason": "Svaret omtaler hverken, at funktionsnedsættelsen skal være velbeskrevet og lægefagligt dokumenteret, eller de momenter, der indgår i vurderingen: hvad den studerende fejler, daglig funktion, behandling og effekt, restsymptomer, medvirken, sygdomsvarighed, gentagelser og tilbagefaldsrisiko. Det nævner kun 'konkrete, varige funktionsnedsættelse' og dens art og grad."
    }
  },
  "overall_notes": "Svaret rammer ved siden af kernen i vejledningens afsnit 3.4.1.2. Det erstatter de eksemplificerende lægefaglige momenter med en snæver arbejdsevnetærskel og tilføjer ikke-understøttede udelukkelser. Svaret indeholder selv 'uden kilde'-markeringer og en advarsel om begrænset grundlag. C04 er sat til met efter reviewerens ordlyd, fordi der er angivet identificerbare kilder, men understøttelsen af påstandene er svag."
}

